<script setup lang="ts">
interface SavedFilter { name:string; filters:Record<string,unknown>; createdAt:string }
const saved=ref<SavedFilter[]>([]);const ready=ref(false)
function load(){try{saved.value=JSON.parse(localStorage.getItem('rea-saved-filters')||'[]') as SavedFilter[]}catch{saved.value=[]}ready.value=true}
onMounted(load)
function remove(index:number){saved.value.splice(index,1);localStorage.setItem('rea-saved-filters',JSON.stringify(saved.value))}
function useFilter(item:SavedFilter){const query=new URLSearchParams(Object.entries(item.filters).filter(([,v])=>v!==undefined&&v!==null&&v!=='').map(([k,v])=>[k,String(v)] as [string,string]));navigateTo(`/filters?${query.toString()}`)}
</script>
<template><div class="page-heading"><div><p class="eyebrow">ANALİZ ARAÇLARI</p><h1>Kayıtlı filtreler</h1><p>Sık kullandığınız arama kombinasyonlarını bu tarayıcıda saklayın ve yeniden kullanın.</p></div><NuxtLink to="/filters" class="button button-primary">＋ Yeni filtre</NuxtLink></div><div class="alert alert-info">Kayıtlı filtreler yalnızca bu tarayıcının yerel depolamasında tutulur; henüz kullanıcı hesabıyla senkronize edilmez.</div><section class="panel"><div class="panel-header"><div><h2>Filtrelerim</h2><p>Bu cihazda saklanan filtre tanımları</p></div><span class="chip">{{ saved.length }} kayıt</span></div><StatePanel v-if="!ready" state="loading"/><StatePanel v-else-if="!saved.length" state="empty" message="Henüz kayıtlı filtre yok. Gelişmiş filtreleme sayfasında bir filtreyi kaydedebilirsiniz."/><div v-else><div v-for="(item,i) in saved" :key="`${item.name}-${item.createdAt}`" class="saved-filter"><div><h3>{{ item.name }}</h3><p>{{ new Intl.DateTimeFormat('tr-TR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(item.createdAt)) }} · {{ Object.keys(item.filters).filter(k=>item.filters[k]!==undefined&&item.filters[k]!==null&&item.filters[k]!=='').length }} parametre</p><div class="table-sub">{{ Object.entries(item.filters).filter(([,v])=>v!==undefined&&v!==null&&v!=='').map(([k,v])=>`${k}: ${v}`).slice(0,4).join(' · ') }}</div></div><div class="table-actions"><button class="button button-secondary" @click="useFilter(item)">Kullan</button><button class="button button-danger" @click="remove(i)">Sil</button></div></div></div></section></template>
